using System;using System.IO;using System.Collections.Generic;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.Rendering;
public static class GroundDetailReview {
 static readonly string[] Names={"Clover_1","Clover_2","Fern_1","Grass_Wispy_Short","Bush_Common_Flowers","Flower_4_Group","Flower_4_Single","Mushroom_Common"};
 const string Models="Assets/ExternalLibrary/stylized-nature-standard/FBX (Unity)/",Prefabs="Assets/SkyIsland/Prefabs/GroundDetails/",Materials="Assets/SkyIsland/Materials/GroundDetails/";
 [Serializable] class Entry {public string name,model,prefab;public int vertices,triangles,materials;public Vector3 size;}
 [Serializable] class Report {public string scope,unity,utc;public Entry[] models;public int assertions;}
 public static void ValidateAndPreview(){
  int checks=0;Action<bool,string> check=(ok,msg)=>{if(!ok)throw new Exception("GROUND DETAIL FAIL "+msg);checks++;};
  Directory.CreateDirectory(Prefabs);Directory.CreateDirectory(Materials);Directory.CreateDirectory("../evidence/assets");
  EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);RenderSettings.ambientLight=new Color(.65f,.73f,.75f);RenderSettings.fog=false;
  var sun=new GameObject("Ground detail preview light").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1.1f;sun.transform.rotation=Quaternion.Euler(50,-35,0);
  var cam=new GameObject("Ground detail preview camera").AddComponent<Camera>();cam.backgroundColor=new Color(.68f,.81f,.83f);cam.clearFlags=CameraClearFlags.SolidColor;cam.orthographic=true;cam.orthographicSize=3.5f;cam.transform.position=new Vector3(0,7,-7);cam.transform.LookAt(new Vector3(0,0,.15f));
  var tileMaterial=new Material(Shader.Find("Standard")){color=new Color(.43f,.59f,.38f)};const string tilePath=Materials+"PreviewBase.mat";if(AssetDatabase.LoadAssetAtPath<Material>(tilePath))UnityEngine.Object.DestroyImmediate(tileMaterial);else AssetDatabase.CreateAsset(tileMaterial,tilePath);tileMaterial=AssetDatabase.LoadAssetAtPath<Material>(tilePath);
  var records=new List<Entry>();for(int index=0;index<Names.Length;index++){
   string name=Names[index],path=Models+name+".fbx";var importer=AssetImporter.GetAtPath(path) as ModelImporter;check(importer!=null,"importer "+name);
   if(importer.materialImportMode!=ModelImporterMaterialImportMode.ImportStandard||importer.materialLocation!=ModelImporterMaterialLocation.InPrefab){importer.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;importer.materialLocation=ModelImporterMaterialLocation.InPrefab;importer.SaveAndReimport();}
   var model=AssetDatabase.LoadAssetAtPath<GameObject>(path);check(model!=null,"native model "+name);var root=new GameObject(name+" · ground detail");var visual=UnityEngine.Object.Instantiate(model,Vector3.zero,Quaternion.identity,root.transform);var renderers=visual.GetComponentsInChildren<Renderer>();check(renderers.Length>0,"renderers "+name);var bounds=renderers[0].bounds;int slots=0;
   foreach(var c in visual.GetComponentsInChildren<Collider>())UnityEngine.Object.DestroyImmediate(c);
   foreach(var renderer in renderers){bounds.Encapsulate(renderer.bounds);var materials=renderer.sharedMaterials;for(int k=0;k<materials.Length;k++){var source=materials[k];check(source!=null&&source.mainTexture!=null,"material texture "+name);string matPath=Materials+name+"-"+slots+".mat";var material=AssetDatabase.LoadAssetAtPath<Material>(matPath);if(!material){material=new Material(source);string texture=source.mainTexture.name.ToLowerInvariant();if(texture.Contains("leav")||texture.Contains("grass")||texture.Contains("flower")){material.SetFloat("_Mode",1);material.SetFloat("_Cutoff",.4f);material.SetInt("_SrcBlend",1);material.SetInt("_DstBlend",0);material.SetInt("_ZWrite",1);material.EnableKeyword("_ALPHATEST_ON");material.renderQueue=2450;}AssetDatabase.CreateAsset(material,matPath);}materials[k]=material;slots++;}renderer.sharedMaterials=materials;}
   check(bounds.size.y>.0001f,"nonzero bounds "+name);float scale=Mathf.Min(.65f/bounds.size.y,1.35f/Mathf.Max(bounds.size.x,bounds.size.z));visual.transform.localScale*=scale;visual.transform.position+=new Vector3(-bounds.center.x*scale,-bounds.min.y*scale,-bounds.center.z*scale);
   int vertices=0,triangles=0;foreach(var filter in visual.GetComponentsInChildren<MeshFilter>()){check(filter.sharedMesh!=null,"mesh "+name);vertices+=filter.sharedMesh.vertexCount;triangles+=filter.sharedMesh.triangles.Length/3;}
   check(vertices>0&&root.GetComponentsInChildren<Collider>().Length==0,"decorative mesh without movement blockers "+name);string prefab=Prefabs+name+".prefab";PrefabUtility.SaveAsPrefabAsset(root,prefab);check(AssetDatabase.LoadAssetAtPath<GameObject>(prefab)!=null,"prefab saved "+name);
   float x=(index%4-1.5f)*2.05f,z=(index/4-.5f)*2.5f;root.transform.position=new Vector3(x,0,z);var tile=GameObject.CreatePrimitive(PrimitiveType.Cube);tile.name="Preview pad "+name;tile.transform.position=new Vector3(x,-.08f,z);tile.transform.localScale=new Vector3(1.75f,.12f,1.85f);tile.GetComponent<Renderer>().sharedMaterial=tileMaterial;
   var label=new GameObject(name+" label").AddComponent<TextMesh>();label.text=name;label.fontSize=42;label.characterSize=.035f;label.anchor=TextAnchor.MiddleCenter;label.color=new Color(.12f,.22f,.23f);label.transform.position=new Vector3(x,.02f,z-.82f);label.transform.rotation=cam.transform.rotation;
   records.Add(new Entry{name=name,model=path,prefab=prefab,vertices=vertices,triangles=triangles,materials=slots,size=bounds.size*scale});
  }
  AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),"Assets/SkyIsland/Scenes/GroundDetailPreview.unity");
  var target=new RenderTexture(1400,900,24);cam.targetTexture=target;cam.Render();RenderTexture.active=target;var image=new Texture2D(1400,900,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1400,900),0,0);image.Apply();File.WriteAllBytes("../evidence/assets/ground-detail-preview.png",image.EncodeToPNG());cam.targetTexture=null;RenderTexture.active=null;UnityEngine.Object.DestroyImmediate(image);UnityEngine.Object.DestroyImmediate(target);
  var report=new Report{scope="8 native FBX models imported, materials/textures checked, collider-free prefabs authored, isolated Unity preview rendered. Main island and public WebGL unchanged; phone performance and gameplay placement pending.",unity=Application.unityVersion,utc=DateTime.UtcNow.ToString("o"),models=records.ToArray(),assertions=checks};File.WriteAllText("../evidence/assets/ground-details-tests.json",JsonUtility.ToJson(report,true));Debug.Log("SKY_GROUND_DETAILS_PASS "+checks+" assets="+records.Count);
 }
}
